            "| ด้าน | คำถามตรวจตนเอง | คะแนน 1–5 |\n|---|---|---|\n| เข้าประเด็น | ผู้ฟังรู้หรือไม่ว่ากำลังตอบคำถามอะไรภายใน 15 วินาทีแรก | ____ |\n| ความถูกต้อง | ตัวอย่างไม่ทำให้เข้าใจหลักการศึกษาอย่างคลาดเคลื่อนหรือไม่ | ____ |\n| การเล่าเรื่อง | ตัวอย่างเห็นภาพและไม่ยาวเกินความจำเป็นหรือไม่ | ____ |\n| ความเป็นธรรมชาติ | พูดเหมือนแลกเปลี่ยน ไม่เหมือนอ่านรายงานหรือไม่ | ____ |\n| จังหวะ | หยุดหลังคำถามสำคัญและไม่เร่งประโยคปิดหรือไม่ | ____ |\n| บทบาทครู/ผู้บริหาร | มีข้อเสนอที่ทำได้จริงโดยไม่เพิ่มภาระเกินจำเป็นหรือไม่ | ____ |\n| การปิดเรื่อง | จบด้วยข้อคิดหนึ่งประเด็นที่จำได้หรือไม่ | ____ |",
            "**บันทึกรอบฝึก:** วันที่ ______ / ข้อที่ ______ / ความยาว ______ / จุดที่ทำได้ดี ______ / สิ่งที่จะปรับรอบหน้า ______"
