      audience:"ผู้บริหารและผู้ตรวจเอกสาร",updated:"24 ต.ค. 2569",edition:"Review Draft 0.1",readTime:"8 นาที",color:"forest",
      coverTitle:"วิทยฐานะ\nเชี่ยวชาญ",coverTop:"M0 REVIEW · DRAFT",
