      pages:[
        {title:"อ่านก่อนใช้: เอกสารฉบับร่าง",kicker:"01 / สถานะเอกสาร",paragraphs:["หนังสือเล่มนี้จัดทำเพื่อให้ตรวจสอบงานเตรียมวิทยฐานะผู้อำนวยการสถานศึกษาเชี่ยวชาญได้ง่าย ไม่ใช่คู่มือราชการที่รับรองเกณฑ์ล่าสุด","M0-A ตรวจดัชนีใจความ 60 ข้อย่อยกับคู่มือ ว 10/2564 แล้ว แต่ยังต้องตรวจฉบับแก้ไขและเกณฑ์ตัดสินที่มีผลใช้บังคับ"],bullets:["ยังไม่ผ่าน Source Lock","ห้ามใช้แทนตัวบท ก.ค.ศ.","ไม่ใช่หลักฐานว่าผู้ขอผ่านการประเมิน"],tip:"ตรวจต้นฉบับทางการทุกครั้งก่อนนำไปใช้ยื่นจริง"},
        {title:"แผนเตรียมงาน M0–M6",kicker:"02 / ภาพรวม",paragraphs:["ใช้ WD Growth Together เป็นแนวคิดงานบริหารเพื่อพัฒนาผู้เรียนรายบุคคลโดยอาศัยข้อมูลและ PLC","แผนแม่บท M0–M6 เป็นกรอบจัดงานและหลักฐาน ไม่ใช่ผลรับรองความสำเร็จ"],bullets:["M0 ตรวจเกณฑ์และเงื่อนไข","M1 ตรวจบัญชีหลักฐานที่มีจริง","งานต่อไปออกแบบการเก็บข้อมูล ผลลัพธ์ และผลงานวิชาการ"],tip:"แผนแม่บท: docs/WD_PRINCIPAL_EXPERT_RANK_MASTER_PLAN_2570.md"},
        {title:"M0-A: โครงสร้างรูบริก",kicker:"03 / ตัวชี้วัด",paragraphs:["แบบ PA 4/บส/สพฐ. วิทยฐานะเชี่ยวชาญในคู่มือปี 2564 มีด้านที่ 1 จำนวน 8 ตัวชี้วัด และด้านที่ 2 จำนวน 4 ตัวชี้วัด","รวมรายการพิจารณา 60 ข้อย่อย ดัชนีใน repository เป็นข้อความถอดใจความ ไม่ใช่การคัดถ้อยคำทางการ"],bullets:["ด้านที่ 1: 8 × 5 = 40 ข้อย่อย","ด้านที่ 2: 4 × 5 = 20 ข้อย่อย","เลขหน้าพิมพ์ 152–157 ตรง PDF หน้า 157–162"],tip:"อ่านทะเบียนฉบับละเอียดที่ docs/pa-expert/M0_A_EXPERT_RUBRIC_MATRIX.md"},
        {title:"วิธีให้คะแนนจากคู่มือปี 2564",kicker:"04 / การอ่านคะแนน",paragraphs:["ด้านที่ 1 คะแนน 1–3 พิจารณาจำนวนข้อที่ผ่านในข้อ 1–3; คะแนน 4 ต้องผ่านครบสามข้อแรกและข้อ 4 หรือ 5; คะแนน 5 ต้องผ่านครบทั้งห้าข้อ","ด้านที่ 2 พิจารณาจำนวนข้อที่ปฏิบัติได้หรือมีผลชัดเจนจากห้าข้อ"],bullets:["คะแนนถ่วงน้ำหนักด้านที่ 1 = คะแนนดิบ × 2.5","คะแนนถ่วงน้ำหนักด้านที่ 2 = คะแนนดิบ × 5","เกณฑ์ตัดสินผ่านฉบับแก้ไขยังไม่ยืนยัน"],tip:"ตัวเลขนี้อ้างอิงแบบประเมินปี 2564 เท่านั้น"},
        {title:"หลักฐาน WD Growth Together",kicker:"05 / จับคู่หลักฐาน",paragraphs:["เสนอใช้ข้อมูล Baseline การวางแผนรายบุคคล PLC การชี้แนะครู และผลประเมินซ้ำเป็นฐานจัดหลักฐานการบริหาร","การมีระบบหรือมีแผนไม่เท่ากับมีผลลัพธ์ที่ตรวจยืนยันแล้ว"],bullets:["แยกหลักฐานเป็น วางแผน / กำลังดำเนินการ / ตรวจยืนยันแล้ว","ผลผู้เรียนต้องเทียบก่อนและหลังอย่างเหมาะสม","ไม่เผยแพร่ข้อมูลผู้เรียนหรือครูรายบุคคล"],tip:"ข้อเสนอหลักฐานไม่ใช่ข้อบังคับของ ก.ค.ศ."},
        {title:"M0-B: ตรวจเอกสารก่อนยื่น",kicker:"06 / DPA และไฟล์",paragraphs:["จัดทะเบียน B01–B10 เพื่อตรวจคุณสมบัติ PA ประจำปี แบบคำขอ วิดีทัศน์ ผลงานทางวิชาการ การอัปโหลด DPA และการคุ้มครองข้อมูล","รายการนี้เป็น checklist ภายในที่ยังต้องเทียบคู่มือ DPA และหนังสือแก้ไขล่าสุด"],bullets:["ตรวจคุณสมบัติและหลักฐานย้อนหลัง","ตรวจข้อกำหนดวิดีทัศน์และผลงานวิชาการ","ตรวจชนิดไฟล์ ขนาดไฟล์ และขั้นตอนส่งจริงจากคู่มือทางการ"],tip:"เอกสาร M0-B: docs/pa-expert/M0_B_SUBMISSION_AND_EVIDENCE_CHECKLIST.md"},
        {title:"สิ่งที่ยังต้องตรวจ",kicker:"07 / Source Lock",paragraphs:["ต้องตรวจข้อความฉบับเต็มของหนังสือแก้ไขเพิ่มเติมที่เกี่ยวข้อง และยืนยันเกณฑ์ตัดสินที่ใช้จริงในวันที่ยื่น","ต้องให้ผู้ตรวจอีกคนทบทวนก่อนถือว่าเอกสารครบถ้วน"],bullets:["ล 679/2566","ล 1144/2567 และ ล 1933/2567","ล 1222/2568 และเอกสารใหม่ที่เกี่ยวข้อง"],tip:"อ้างอิงทะเบียนที่ docs/pa-expert/PA_EXPERT_RUBRIC_SOURCE_REVIEW.md"},
        {title:"วิธีส่งข้อแก้ไข",kicker:"08 / ตรวจทาน",paragraphs:["เมื่อพบข้อความหรือเกณฑ์ไม่ตรงต้นฉบับ ให้ระบุรหัสตัวชี้วัด เลขหน้า เอกสารฉบับที่ใช้ และคำเสนอแก้ไข","เอกสารหลักใน GitHub ปรับปรุงได้โดยไม่ต้องประกาศว่าผ่าน Source Lock ก่อนเวลา"],bullets:["M0-A: ทะเบียนรูบริก","M0-B: เงื่อนไขยื่นและหลักฐาน","เก็บข้อมูลส่วนบุคคลไว้ในพื้นที่จำกัดสิทธิ์เท่านั้น"],tip:"ฉบับนี้เผยแพร่เพื่อช่วยตรวจสอบ ไม่ใช่การรับรองผลการประเมิน"}
      ]
